 QuickActivity activity;
 @Before public void setup(){RuntimeEnvironment.getApplication().deleteDatabase("pocket.db");activity=Robolectric.buildActivity(QuickActivity.class).setup().get();}
 EditText field(View view,String hint){if(view instanceof EditText&&hint.equals(((EditText)view).getHint().toString()))return (EditText)view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){EditText found=field(((ViewGroup)view).getChildAt(i),hint);if(found!=null)return found;}return null;}
 void save(){org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();activity.activeForm.getButton(AlertDialog.BUTTON_POSITIVE).performClick();org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();}
 @Test public void debtEntryPartialRepaymentOverpaymentAndCascadeDelete()throws Exception{
  activity.quickKind="lent";activity.entry(-1);View form=activity.activeForm.getWindow().getDecorView();field(form,"0.00").setText("500.00");field(form,"Person's name").setText("Sample Person");save();
  assertEquals(String.valueOf(org.robolectric.shadows.ShadowToast.getTextOfLatestToast()),1,activity.sum("SELECT count(*) FROM tx"));assertEquals(50000,activity.debtTotal("lent"));assertEquals(-50000,activity.balance("Cash"));String uuid;long id;try(android.database.Cursor c=activity.db.rawQuery("SELECT id,uuid FROM tx WHERE kind='lent'",null)){assertTrue(c.moveToFirst());id=c.getLong(0);uuid=c.getString(1);}
  activity.repayment(uuid,-1);form=activity.activeForm.getWindow().getDecorView();field(form,"0.00").setText("200.00");save();assertEquals(30000,activity.debtTotal("lent"));assertEquals(-30000,activity.balance("Cash"));
  activity.repayment(uuid,-1);form=activity.activeForm.getWindow().getDecorView();field(form,"0.00").setText("400.00");save();assertTrue(activity.activeForm.isShowing());assertEquals(2,activity.sum("SELECT count(*) FROM tx"));assertEquals(30000,activity.debtTotal("lent"));activity.activeForm.dismiss();
  activity.validate(new org.json.JSONObject(new String(activity.data(),java.nio.charset.StandardCharsets.UTF_8)));
  activity.confirmDelete(id);AlertDialog confirm=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();confirm.getButton(AlertDialog.BUTTON_POSITIVE).performClick();org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals(0,activity.sum("SELECT count(*) FROM tx"));assertEquals(0,activity.balance("Cash"));assertEquals(2,activity.sum("SELECT count(*) FROM sync_outbox WHERE operation='delete'"));
 }
 @Test public void originalCategoryMarksAndLauncherVariants()throws Exception{
  Bitmap sheet=Bitmap.createBitmap(1080,1680,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(sheet);canvas.drawColor(Color.WHITE);Paint label=new Paint(Paint.ANTI_ALIAS_FLAG);label.setColor(0xff17251f);label.setTextSize(24);
  for(int i=0;i<activity.cats.length;i++){int x=40+(i%4)*270,y=28+(i/4)*230;CategoryMark mark=new CategoryMark(i,0xff006b53);mark.setBounds(x+65,y,x+177,y+112);mark.draw(canvas);canvas.drawText(activity.cats[i],x+20,y+158,label);}
  new File("/downloads/hisab-v2/qa").mkdirs();try(FileOutputStream out=new FileOutputStream("/downloads/hisab-v2/qa/category-marks.png")){sheet.compress(Bitmap.CompressFormat.PNG,100,out);}
  for(String chosen:AppIcon.COLORS){AppIcon.choose(activity,chosen);for(String color:AppIcon.COLORS){int state=activity.getPackageManager().getComponentEnabledSetting(new ComponentName(activity,"in.aicon.pocket.Icon"+color));assertEquals(chosen.equals(color)?android.content.pm.PackageManager.COMPONENT_ENABLED_STATE_ENABLED:android.content.pm.PackageManager.COMPONENT_ENABLED_STATE_DISABLED,state);}}
  AppIcon.choose(activity,"Orange");
  Bitmap icons=Bitmap.createBitmap(1080,460,Bitmap.Config.ARGB_8888);Canvas ic=new Canvas(icons);ic.drawColor(0xfff4f8f6);for(int i=0;i<AppIcon.COLORS.length;i++){String color=AppIcon.COLORS[i];int resource=activity.getResources().getIdentifier(i==0?"ic_launcher":"ic_launcher_"+color.toLowerCase(java.util.Locale.ROOT),"mipmap",activity.getPackageName());android.graphics.drawable.Drawable drawable=activity.getDrawable(resource);int x=35+i*176;drawable.setBounds(x,80,x+130,210);drawable.draw(ic);ic.drawText(color,x,275,label);}try(FileOutputStream out=new FileOutputStream("/downloads/hisab-v2/qa/launcher-variants.png")){icons.compress(Bitmap.CompressFormat.PNG,100,out);}
 }
 @Test public void darkMalayalamRenders()throws Exception{activity.dark=true;activity.ml=true;activity.render();screenshot("overview-dark-malayalam",activity.root);activity.quickKind="borrowed";activity.entry(-1);screenshot("borrowed-dark-malayalam",activity.activeForm.getWindow().getDecorView());}
 @Test public void customizationRenamePreservesDebtLinksTransfersBudgetsAndBackup()throws Exception{
  debtPeopleRender();String loan="11111111-1111-4111-8111-111111111111";
  ContentValues p=new ContentValues();p.put("uuid",java.util.UUID.randomUUID().toString());p.put("kind","repay_in");p.put("amount",20000);p.put("day","2026-11-11");p.put("account","Cash");p.put("dest","");p.put("category","Debt");p.put("note","");p.put("person","Sample Person");p.put("loan",loan);activity.db.insertOrThrow("tx",null,p);
  p.put("uuid",java.util.UUID.randomUUID().toString());p.put("kind","transfer");p.put("amount",10000);p.put("account","Bank");p.put("dest","Cash");p.put("category","Transfer");p.put("person","");p.put("loan","");activity.db.insertOrThrow("tx",null,p);activity.db.execSQL("INSERT INTO budgets(category,amount) VALUES('Food',450000)");activity.refreshCatalog();long before=activity.balance("Cash");
  CatalogStore.Item cash=activity.catalog.find("account","Cash"),person=activity.catalog.find("person","Sample Person"),food=activity.catalog.find("category","Food");
  activity.catalog.put(cash.id,"account","Daily purse",22,"Teal");activity.catalog.put(person.id,"person","Renamed person",16,"Rose");activity.catalog.put(food.id,"category","Dining",0,"Violet");activity.render();assertEquals(before,activity.balance("Daily purse"));assertEquals(0,activity.sum("SELECT count(*) FROM tx WHERE account='Cash' OR dest='Cash'"));assertEquals(2,activity.sum("SELECT count(*) FROM tx WHERE person='Renamed person'"));assertEquals(480000,activity.debtTotal("lent"));assertEquals(1,activity.sum("SELECT count(*) FROM budgets WHERE category='Dining'"));assertEquals(0,activity.sum("SELECT count(*) FROM catalog WHERE name='Food' OR name='Cash'"));
  org.json.JSONObject backup=new org.json.JSONObject(new String(activity.data(),java.nio.charset.StandardCharsets.UTF_8));activity.validate(backup);activity.catalog.put(null,"account","Temporary account",22,"Blue");activity.restore(backup);assertNull(activity.catalog.find("account","Temporary account"));assertEquals(before,activity.balance("Daily purse"));assertEquals(cash.id,activity.catalog.find("account","Daily purse").id);assertEquals(person.id,activity.catalog.find("person","Renamed person").id);assertEquals("Violet",activity.catalog.find("category","Dining").color);
  activity.entry(-1);View form=activity.activeForm.getWindow().getDecorView();field(form,"0.00").setText("10.00");save();assertEquals(1,activity.sum("SELECT count(*) FROM tx WHERE kind='expense' AND account='Daily purse'"));
 }
 @Test public void customizationRejectsDuplicatesAndFailedRestoreIsAtomic()throws Exception{
  CatalogStore.Item food=activity.catalog.find("category","Food");try{activity.catalog.put(food.id,"category","groceries",0,"Rose");fail();}catch(IllegalArgumentException expected){}assertNotNull(activity.catalog.find("category","Food"));
  org.json.JSONObject broken=new org.json.JSONObject(new String(activity.data(),java.nio.charset.StandardCharsets.UTF_8));org.json.JSONArray entities=broken.getJSONArray("catalog");entities.put(entities.getJSONObject(0));try{activity.restore(broken);fail();}catch(Exception expected){}assertEquals(28,activity.catalog.list("category").size());
  activity.catalog.put(null,"category","Custom category",27,"Blue");activity.ml=true;activity.render();assertEquals("Custom category",activity.cat("Custom category"));activity.editCatalog("category",activity.catalog.find("category","Custom category"));screenshot("custom-category-editor-malayalam",activity.activeForm.getWindow().getDecorView());
 }
