 @Test public void budgetAndGoalEditingPreserveIdentity()throws Exception{activity.budget();field(activity.activeForm.getWindow().getDecorView(),"0.00").setText("300.00");save();String uuid;try(android.database.Cursor c=activity.db.rawQuery("SELECT uuid FROM budgets WHERE category='Food'",null)){assertTrue(c.moveToFirst());uuid=c.getString(0);}activity.editBudget("Food");field(activity.activeForm.getWindow().getDecorView(),"0.00").setText("450.00");screenshot("budget-edit",activity.activeForm.getWindow().getDecorView());save();try(android.database.Cursor c=activity.db.rawQuery("SELECT uuid,amount FROM budgets WHERE category='Food'",null)){assertTrue(c.moveToFirst());assertEquals(uuid,c.getString(0));assertEquals(45000,c.getLong(1));}activity.goal(-1);View f=activity.activeForm.getWindow().getDecorView();field(f,"For example, a laptop").setText("Laptop");field(f,"0.00").setText("500.00");save();long id;try(android.database.Cursor c=activity.db.rawQuery("SELECT id,uuid FROM goals",null)){assertTrue(c.moveToFirst());id=c.getLong(0);uuid=c.getString(1);}activity.goal(id);f=activity.activeForm.getWindow().getDecorView();field(f,"For example, a laptop").setText("New laptop");save();try(android.database.Cursor c=activity.db.rawQuery("SELECT uuid,name FROM goals",null)){assertTrue(c.moveToFirst());assertEquals(uuid,c.getString(0));assertEquals("New laptop",c.getString(1));}activity.validate(new org.json.JSONObject(new String(activity.data(),java.nio.charset.StandardCharsets.UTF_8)));}
 @Test public void largeIconChooserRenders()throws Exception{activity.chooseOriginalIcon(0,"System",n->{});screenshot("large-icon-picker",org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog().getWindow().getDecorView());activity.catalogList("category");screenshot("category-list-large-icons",org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog().getWindow().getDecorView());}
 @Test public void preferencesFormattingDefaultsRenameAndBackup()throws Exception{activity.settings.put("grouping","Indian");assertEquals("₹12,34,567.89",activity.ru(123456789));activity.settings.put("grouping","International");activity.settings.put("amountStyle","Code");assertEquals("INR 1,234,567.89",activity.ru(123456789));activity.settings.put("dateFormat","dd/MM/yyyy");assertEquals("11/11/2026",activity.displayDate("2026-11-11"));CatalogStore.Item account=activity.catalog.find("account","Wallet");activity.settings.put("defaultAccount",account.id);activity.catalog.put(account.id,"account","Daily wallet",22,"Rose");activity.refreshCatalog();assertEquals("Daily wallet",activity.defaultEntity("account","Cash"));activity.settings.put("home","quick,recent,summary");activity.settings.put("palette","Violet");activity.render();screenshot("custom-home-violet",activity.root);org.json.JSONObject data=new org.json.JSONObject(new String(activity.data(),java.nio.charset.StandardCharsets.UTF_8));activity.settings.put("dateFormat","yyyy-MM-dd");activity.restore(data);assertEquals("dd/MM/yyyy",activity.settings.get("dateFormat"));assertEquals("quick,recent,summary",activity.settings.get("home"));activity.preferencesMenu();screenshot("preferences-menu",org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog().getWindow().getDecorView());}
 @Test public void oldBackupWithMultipleBudgetsAndGoalsMigrates()throws Exception{org.json.JSONObject old=new org.json.JSONObject().put("schema",1).put("tx",new org.json.JSONArray()).put("budgets",new org.json.JSONArray().put(new org.json.JSONObject().put("category","Food").put("amount",10000)).put(new org.json.JSONObject().put("category","Home").put("amount",20000))).put("goals",new org.json.JSONArray().put(new org.json.JSONObject().put("id",1).put("name","First").put("target",10000).put("saved",0)).put(new org.json.JSONObject().put("id",2).put("name","Second").put("target",20000).put("saved",0)));activity.restore(old);assertEquals(2,activity.sum("SELECT count(DISTINCT uuid) FROM budgets"));assertEquals(2,activity.sum("SELECT count(DISTINCT uuid) FROM goals"));activity.validate(new org.json.JSONObject(new String(activity.data(),java.nio.charset.StandardCharsets.UTF_8)));}
 @Test public void invalidPreferenceAndFractionalBackupLeaveDataUnchanged()throws Exception{try{activity.settings.put("home","quick,quick");fail();}catch(IllegalArgumentException expected){}try{activity.settings.put("palette","Orange");fail();}catch(IllegalArgumentException expected){}org.json.JSONObject data=new org.json.JSONObject(new String(activity.data(),java.nio.charset.StandardCharsets.UTF_8));data.getJSONObject("preferences").put("dateFormat","garbage");try{activity.restore(data);fail();}catch(Exception expected){}assertEquals("yyyy-MM-dd",activity.settings.get("dateFormat"));}
