 @Test public void staleUiFormCannotWriteAndFailedSaveRollsBack()throws Exception{activity.entry(-1);field(activity.activeForm.getWindow().getDecorView(),"0.00").setText("100.00");activity.session.invalidateForms();save();assertTrue(activity.activeForm.isShowing());assertEquals(0,activity.sum("SELECT count(*) FROM tx"));activity.activeForm.dismiss();try{activity.mutate(()->{try{activity.catalog.put(null,"category","Rolled back category",27,"Rose");}catch(Exception e){throw new RuntimeException(e);}activity.db.execSQL("INSERT INTO tx(kind,amount,day,account,dest,category,note,uuid,person,loan) VALUES('expense',-1,'2026-11-11','Cash','','Food','','22222222-2222-4222-8222-222222222222','','')");});fail();}catch(IllegalArgumentException expected){}assertEquals(0,activity.sum("SELECT count(*) FROM tx"));assertNull(activity.catalog.find("category","Rolled back category"));assertFalse(java.util.Arrays.asList(activity.cats).contains("Rolled back category"));}
 @Test public void openEntryCannotRecreateRenamedAccountFromStaleChoices()throws Exception{activity.entry(-1);field(activity.activeForm.getWindow().getDecorView(),"0.00").setText("10.00");CatalogStore.Item cash=activity.catalog.find("account","Cash");activity.mutate(()->{try{activity.catalog.put(cash.id,"account","Daily cash",22,"Teal");}catch(Exception e){throw new RuntimeException(e);}});save();assertTrue(activity.activeForm.isShowing());assertEquals(0,activity.sum("SELECT count(*) FROM tx"));assertNull(activity.catalog.find("account","Cash"));assertNotNull(activity.catalog.find("account","Daily cash"));}
 @Test public void twoThousandEntryLocalMutationPassesDirectAndBackupValidation()throws Exception{long started=System.nanoTime();activity.mutate(()->{android.database.sqlite.SQLiteStatement insert=activity.db.compileStatement("INSERT INTO tx(uuid,kind,amount,day,account,dest,category,note,person,loan) VALUES(?,'expense',100,'2026-11-11','Cash','','Food','','','')");try{for(int n=0;n<2000;n++){insert.bindString(1,java.util.UUID.randomUUID().toString());insert.executeInsert();}}finally{insert.close();}});long elapsed=(System.nanoTime()-started)/1000000;assertEquals(2000,activity.sum("SELECT count(*) FROM tx"));activity.validate(new org.json.JSONObject(new String(activity.data(),java.nio.charset.StandardCharsets.UTF_8)));System.out.println("Simulation only: atomic 2000-row insert plus direct validation "+elapsed+"ms. Not a device performance benchmark.");}
 @Test public void removeUnusedEntityResetsDefaultsAndKeepsReferencedHistory()throws Exception{CatalogStore.Item custom=activity.catalog.put(null,"category","Unused category",27,"Rose");activity.settings.put("defaultCategory",custom.id);activity.mutate(()->{try{activity.catalog.removeUnused(custom.id);}catch(Exception e){throw new RuntimeException(e);}});assertNull(activity.catalog.find("category","Unused category"));assertEquals("",activity.settings.get("defaultCategory"));activity.refreshCatalog();assertNull(activity.catalog.find("category","Unused category"));debtPeopleRender();CatalogStore.Item person=activity.catalog.find("person","Sample Person");try{activity.catalog.removeUnused(person.id);fail();}catch(IllegalArgumentException expected){}assertEquals(500000,activity.debtTotal("lent"));assertNotNull(activity.catalog.find("person","Sample Person"));activity.removeCatalog(person);screenshot("referenced-person-protected",org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog().getWindow().getDecorView());}
