 void screenshot(String name,View v)throws Exception{int w=1080,h=2400;v.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));v.layout(0,0,w,h);if(name.endsWith("-bottom")&&activity.body.getParent() instanceof ScrollView){ScrollView scroll=(ScrollView)activity.body.getParent();scroll.scrollTo(0,Math.max(0,activity.body.getHeight()-scroll.getHeight()));}Bitmap bitmap=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);v.draw(new Canvas(bitmap));new File("/downloads/hisab-v2/qa").mkdirs();try(FileOutputStream out=new FileOutputStream("/downloads/hisab-v2/qa/"+name+".png")){assertTrue(bitmap.compress(Bitmap.CompressFormat.PNG,100,out));}}
